contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount, uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        require(depositAmount > 0);

        c.depositsCount(); if (__ESBMC_reverted()) return;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeOwnerBalance = address(this).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterOwnerBalance = address(this).balance;

        assert(afterBalance == 0 && afterDeposits == beforeDeposits && afterOwnerBalance >= beforeOwnerBalance);
    }
}

