// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(depositAmount > 0);
        try c.depositsCount() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint beforeBalance = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeOwnerBalance = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        uint afterBalance = address(c).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterOwnerBalance = address(this).balance;
        assertTrue(afterBalance == 0 && afterDeposits == beforeDeposits && afterOwnerBalance >= beforeOwnerBalance);
    }

    function testFuzz_run(uint256 amount, uint256 depositAmount) public {
        _run(amount, depositAmount);
    }

    receive() external payable {}
}
